(function() {'use strict';if (typeof window !== 'undefined' && window.SessionFreeAuth) {return;}class SessionFreeAuth {constructor(wallet, options = {}) {this.wallet = wallet;this.debug = options.debug || false;this.verificationCache = new Map();this.cacheTTL = options.cacheTTL || 5 * 60 * 1000;this.eventSource = null;this.reconnectAttempts = 0;this.maxReconnectAttempts = 5;this.syncInterval = options.syncInterval || 10 * 60 * 1000;this.lastSync = 0;this.setupRevocationListener();this.startPeriodicSync();if (this.debug) {console.log('🔐 Session-Free Auth initialized');console.log(` Cache TTL: ${this.cacheTTL / 1000}s`);console.log(` Sync interval: ${this.syncInterval / 1000}s`);}}setupRevocationListener() {try {this.eventSource = new EventSource('/api/events/revocations', {withCredentials: true});this.eventSource.addEventListener('revocation', (event) => {try {const data = JSON.parse(event.data);const {credential_id, site_id, credential_type} = data;const ourSite = window.location.hostname;if (site_id === null || site_id === ourSite) {this.verificationCache.delete(credential_id);if (this.debug) {console.log(`[SessionFreeAuth] Cache invalidated for ${credential_id} (type: ${credential_type}, site: ${site_id || 'global'})`);}this.wallet.syncRevocations().catch(e => {if (this.debug) console.warn('[SessionFreeAuth] Revocation sync failed:', e);});} else {if (this.debug) {console.log(`[SessionFreeAuth] Skipping revocation for ${site_id} (we're ${ourSite})`);}}} catch (error) {if (this.debug) {console.error('[SessionFreeAuth] Failed to process revocation event:', error);}}});this.eventSource.addEventListener('session_invalidated', (event) => {try {const data = JSON.parse(event.data);this.verificationCache.clear();if (this.debug) {console.log(`[SessionFreeAuth] Session invalidated for wallet ${data.wallet_id?.substring(0, 8)}... — cache cleared`);}window.dispatchEvent(new CustomEvent('lemma:session-invalidated', {detail: { wallet_id: data.wallet_id, timestamp: data.timestamp }}));} catch (error) {if (this.debug) {console.error('[SessionFreeAuth] Failed to process session_invalidated event:', error);}}});this.eventSource.addEventListener('session_restored', (event) => {try {const data = JSON.parse(event.data);if (this.debug) {console.log(`[SessionFreeAuth] Session restored for wallet ${data.wallet_id?.substring(0, 8)}...`);}window.dispatchEvent(new CustomEvent('lemma:session-restored', {detail: { wallet_id: data.wallet_id, expires_at: data.expires_at, timestamp: data.timestamp }}));} catch (error) {if (this.debug) {console.error('[SessionFreeAuth] Failed to process session_restored event:', error);}}});this.eventSource.addEventListener('connected', () => {this.reconnectAttempts = 0;if (this.debug) {console.log('[SessionFreeAuth] SSE event stream connected (revocation + session events)');}});this.eventSource.addEventListener('error', () => {if (this.eventSource.readyState === EventSource.CLOSED) {if (this.debug) {console.warn('[SessionFreeAuth] Event stream closed, reconnecting...');}this.reconnectEventSource();}});} catch (error) {if (this.debug) {console.warn('[SessionFreeAuth] Event-driven listener not available, using periodic sync', error);}}}reconnectEventSource() {if (this.reconnectAttempts >= this.maxReconnectAttempts) {if (this.debug) {console.error('❌ Max reconnect attempts reached, falling back to periodic sync');}return;}this.reconnectAttempts++;const delay = Math.min(1000 * Math.pow(2, this.reconnectAttempts), 30000);setTimeout(() => {if (this.debug) {console.log(`🔄 Reconnecting revocation stream (attempt ${this.reconnectAttempts})...`);}this.setupRevocationListener();}, delay);}startPeriodicSync() {setInterval(() => {const age = Date.now() - this.lastSync;if (age > this.syncInterval) {this.wallet.syncRevocations().then(() => {this.lastSync = Date.now();if (this.debug) {console.log('🔄 Periodic Bloom filter sync complete');}}).catch(error => {if (this.debug) {console.warn('⚠️ Periodic sync failed:', error);}});}}, this.syncInterval);}async isAuthenticated(credential, options = {}) {const now = Date.now();const cached = this.verificationCache.get(credential.id);const needsFresh = options.forceFresh || options.sensitive;if (!needsFresh && cached) {const age = now - cached.timestamp;if (age < this.cacheTTL) {if (this.debug) {console.log(`✅ Cache hit for ${credential.id} (age: ${Math.floor(age/1000)}s)`);}return cached.verified;}}if (this.debug) {console.log(`🔐 Verifying ${credential.id} (cache ${cached ? 'expired' : 'miss'})`);}const result = await this.wallet.verifyCredential(credential);this.verificationCache.set(credential.id, {verified: result.verified,timestamp: now,lastChecked: now});return result.verified;}async verifyForSensitiveOperation(credential) {return this.isAuthenticated(credential, {forceFresh: true, sensitive: true});}async batchIsAuthenticated(credentials) {const results = new Map();const promises = credentials.map(async (credential) => {const authenticated = await this.isAuthenticated(credential);results.set(credential.id, authenticated);});await Promise.all(promises);return results;}invalidate(credentialId) {this.verificationCache.delete(credentialId);if (this.debug) {console.log(`🗑️ Cache invalidated for ${credentialId}`);}}clearCache() {this.verificationCache.clear();if (this.debug) {console.log('🗑️ Verification cache cleared');}}getCacheStats() {const now = Date.now();let fresh = 0;let stale = 0;for (const [id, cached] of this.verificationCache) {const age = now - cached.timestamp;if (age < this.cacheTTL) {fresh++;} else {stale++;}}return {total: this.verificationCache.size,fresh,stale,hitRate: fresh / Math.max(1, this.verificationCache.size)};}destroy() {if (this.eventSource) {this.eventSource.close();}this.verificationCache.clear();if (this.debug) {console.log('🔐 Session-Free Auth destroyed');}}}if (typeof window !== 'undefined') {window.SessionFreeAuth = SessionFreeAuth;}if (typeof module !== 'undefined' && module.exports) {module.exports = {SessionFreeAuth};}})();